group defaultmap(source bundle: Bundle, target ds: dasta){

		bundle -> ds.is as t1 then {


			bundle.entry as x1 -> t1.ip as y then ip_ip(x1,y) "rule1";
		} "rule2";

}
group ip_ip(source entry: Bundle, target ip: ip){

		entry.resource as s1 where $this.ofType(FHIR.Patient) -> ip then {
			s1.id as x -> ip.guid = x "rule1";
		} "rule2";
		entry.resource as s1 where $this.ofType(FHIR.Patient) -> ip then {
			s1.identifier as s2 -> ip then {
				s2.value as x -> ip.id_pac = x "rule3";
			} "rule4";
		} "rule5";
		entry -> ip.rodcis as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.identifier as s2 -> t1 then {
					s2.value as x -> t1.txt = x "rule6";
				} "rule7";
			} "rule8";
		} "rule9";
		entry -> ip.rip as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.identifier as s2 -> t1 then {
					s2.value as x -> t1.txt = x "rule10";







					s2.period as s3 -> ip then {
						s2.value as x1 -> ip then {
						 s2.system as x2 -> ip then { 
						   s3.end as x3 -> ip.id_card as y then ip_id_card(x3,x2,x1,y) "rule11";
						 }"";
						}"";
					
					} "rule12";
				} "rule13";
			} "rule14";
		} "rule15";

		entry.resource as s1 where $this.ofType(FHIR.Patient) -> ip then {
			s1.identifier as s2 -> ip then {





				s2.period as s3 -> ip then {
					s2.value as x1 -> ip then {
					 s2.system as x2 -> ip then {
					  s3.end as x3 -> ip.passport as y then ip_passport(x3,x2,x1,y) "rule16";
					 }"";
					}"";
				} "rule17";
			} "rule18";
		} "rule19";

		entry -> ip.jmeno as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.name as s2 -> t1 then {
					s2.given as x -> t1.txt = x "rule20";
				} "rule21";
			} "rule22";
		} "rule23";
		entry -> ip.prijmeni as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.name as s2 -> t1 then {
					s2.family as x -> t1.txt = x "rule24";
				} "rule25";
			} "rule26";
		} "rule27";
		entry -> ip.titul_pred as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.name as s2 -> t1 then {
					s2.prefix as x -> t1.txt = x "rule28";
				} "rule29";
			} "rule30";
		} "rule31";
		entry -> ip.titul_za as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.name as s2 -> t1 then {
					s2.suffix as x -> t1.txt = x "rule32";
				} "rule33";
			} "rule34";
		} "rule35";
		entry -> ip.dat_dn as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.birthDate as x -> t1.txt = x "rule36";
			} "rule37";
		} "rule38";
		entry -> ip.misto_nar as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.extension as s2 -> t1 then {
					s2.valueAddress as s3 -> t1 then {
						s3.city as x -> t1.txt = x "rule39";
					} "rule40";
				} "rule41";
			} "rule42";
		} "rule43";
		entry -> ip.stat_pris as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.extension as s2 -> t1 then {
					s2.extension as s3 -> t1 then {
						s3.valueCodeableConcept as s4 -> t1 then {
							s4.coding as s5 -> t1 then {
								s5.code as x -> t1.txt = x "rule44";
							} "rule45";
						} "rule46";
					} "rule47";
				} "rule48";
			} "rule49";
		} "rule50";
		entry -> ip.dat_de as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.deceasedDateTime as x -> t1.txt = x "rule51";
			} "rule52";
		} "rule53";
		entry -> ip.sex as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.gender as x -> t1.txt = x "rule54";
			} "rule55";
		} "rule56";
		entry -> ip.sex_klin as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.gender as x -> t1.txt = x "rule57";
			} "rule58";
		} "rule59";
		entry -> ip.rod_prijm as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.name as s2 -> t1 then {
					s2.family as x -> t1.txt = x "rule60";
				} "rule61";
			} "rule62";
		} "rule63";
		entry -> ip.jazyk as t1 then {
			entry.resource as s1 where $this.ofType(FHIR.Patient) -> t1 then {
				s1.communication as s2 -> t1 then {
					s2.language as s3 -> t1 then {
						s3.coding as s4 -> t1 then {
							s4.code as x -> t1.jazyk_klic = x "rule64";


							s4.display as x -> t1.jazyk_text = x "rule65";
						} "rule66";
					} "rule67";

					s2.preferred as x -> t1.pref = translate(x,'#cm9135','code') "rule68";

					s2.language as s3 -> t1 then {
						s3.text as x -> t1.pozn = x "rule69";


						entry -> t1.ind_oprav_sd = 'N' "rule70";
						/*s1.name as s4 -> t1 then {
							s4.prefix as x1 -> t1 then{
								s4.given as x2 -> t1 then{
							       s4.suffix as x3 -> append(x1, ' ', x2, ' ', ' ', x3) as Name then {
								      s1.address as adr -> t1 then{
									   s1.telecom as tel -> t1.a as y then adresa(tel,adr,Name,y) "rule73";
									  } "";
								   }"";
								}"";
							}"";
						}"";*/
					} "rule74";
				} "rule75";
			} "rule76";
		} "rule77";

		entry.resource as s1 where $this.ofType(FHIR.Patient) -> ip then {
			s1.identifier as s2 -> ip then {




				s2.value as x1 -> ip then{ 
					s2.system as x2 -> ip.ipi_o as y then ip_ipi_o(x1,x2,y) "rule78";
				}"";
			} "rule79";
		} "rule80";

		entry.resource as s1 where $this.ofType(FHIR.Patient) -> ip then {
			s1.identifier as s2 -> ip then {




				s2.value as x1 -> ip then {
				 s2.system as x2 -> ip.ipi_v as y then ip_ipi_v(x1,x2,y) "rule81";
				}"";
			} "rule82";
		} "rule83";

		entry -> ip.pv_pac as t1 then {
			entry -> t1.typ_pv = 'ZP' "rule84";
		} "rule85";
		entry -> ip.pv_pac as t1 then {
			entry -> t1.pv_zp as t2 then {
				entry -> t2.cispoj as t3 then {
					entry.resource as s1 where $this.ofType(FHIR.Patient) -> t3 then {
						s1.identifier as s2 -> t3 then {
							s2.value as x -> t3.txt = x "rule86";
						} "rule87";
					} "rule88";
				} "rule89";
			} "rule90";
		} "rule91";
		entry -> ip.pv_pac as t1 then {
			entry -> t1.pv_zp as t2 then {
				entry -> t2.kodpoj as t3 then {
					entry.resource as s1 where $this.ofType(FHIR.Patient) -> t3 then {
						s1.identifier as s2 -> t3 then {
							s2.assigner as s3 -> t3 then {
								s3.identifier as s4 -> t3 then {
									s4.value as x -> t3.txt = x "rule92";

									entry -> ip.ku as t4 then {






										entry.Composition as x1 -> t4 then{
										 entry.Organization as x2 -> t4.ku_z as y then ku_z(x2,x1,bundle,y) "rule93";
										}"";
									} "rule94";
								} "rule95";
							} "rule96";
						} "rule97";
					} "rule98";
				} "rule99";
			} "rule100";
		} "rule101";

}
group adresa(source ContactPoint: ContactPoint, source Address: Address, source Name: string, target a: a){


		Address.use as x -> a.typ = translate(x,'#cm2691','code') "rule1";


		Address.type as x -> a.ind_kont = translate(x,'#cm9171','code') "rule2";

		ContactPoint -> a.dat_od as t1 then {
			Address.period as s3 -> t1 then {
				s3.start as x -> t1.txt = x "rule3";
			} "rule4";
		} "rule5";
		ContactPoint -> a.dat_do as t1 then {
			Address.period as s3 -> t1 then {
				s3.end as x -> t1.txt = x "rule6";
			} "rule7";
		} "rule8";
		ContactPoint -> a.jmeno as t1 then {
			Name as x -> t1.txt = x "rule9";
		} "rule10";
		//ContactPoint -> a.adr as t1 then {
		//	y0 as x -> t1.txt = x "rule11";
		//} "rule12";
		ContactPoint -> a.psc as t1 then {
			Address.postalCode as x -> t1.txt = x "rule13";
		} "rule14";
		ContactPoint -> a.mesto as t1 then {
			Address.city as x -> t1.txt = x "rule15";
		} "rule16";
		ContactPoint -> a.stat as t1 then {
			Address.country as x -> t1.txt = x "rule17";




			ContactPoint -> a.as as y then adresa_spojeni(ContactPoint,y) "rule18";
		} "rule19";

}
group adresa_spojeni(source ContactPoint: ContactPoint, target as: as){


		ContactPoint as x -> as = x "rule1";


		ContactPoint.rank as x -> as.poradi = x "rule2";


		ContactPoint.system as x -> as.typ = translate(x,'#cm2706','code') "rule3";

		ContactPoint -> as.obsah as t1 then {
			ContactPoint.value as x -> t1.txt = x "rule4";
		} "rule5";
}
