group ku_z(source Organization: Organization, source Composition: Composition, source entry: Bundle, target ku_zType: ku_zType){

/* 
		y0 as x -> ku_zType.guid = x "rule1";


		y0 as x -> ku_zType.typku = x "rule2";

*/
		Organization -> ku_zType.fazespec = 'ZR' "rule3";


//		y0 as x -> ku_zType.idku = x "rule4";

		Organization -> ku_zType.dat_prov as t1 then {
//			y0 as x -> t1.txt = x "rule5";




			Organization -> ku_zType.p_pracoviste as y then pracoviste(Organization,y) "rule6";
		} "rule7";

		Organization -> ku_zType.text as t1 then {
			Organization -> t1.ptext as t2 then {
				Composition.text as s3 -> t2 then {
					s3.div as s4 -> t2 then {
						s4.text as s5 -> t2 then {
							s5.txt as x -> t2.txt = x "rule8";




							Organization -> ku_zType.ku_z_lab as y then ku_z_lab(bundle,y) "rule9";
						} "rule10";
					} "rule11";
				} "rule12";
			} "rule13";
		} "rule14";

}
group pracoviste(source Organization: Organization, target pracovisteType: pracovisteType){

		Organization.identifier as s1 where $this.system='https://ncez.mzcr.cz/fhir/sid/ico' -> pracovisteType then {
			s1.value as x -> pracovisteType.ico = x "rule1";
		} "rule2";
		Organization.identifier as s1 where $this.system='https://ncez.mzcr.cz/fhir/sid/icz' -> pracovisteType then {
			s1.value as x -> pracovisteType.icz = x "rule3";
		} "rule4";
		Organization.identifier as s1 where $this.system='https://ncez.mzcr.cz/fhir/sid/icp' -> pracovisteType then {
			s1.value as x -> pracovisteType.icp = x "rule5";
		} "rule6";
		Organization.type as s1 -> pracovisteType then {
			s1.coding as s2 where $this.system='https://ncez.mzcr.cz/fhir/CodeSystem/cz-drzar' -> pracovisteType then {
				s2.code as x -> pracovisteType.odb = x "rule7";
			} "rule8";
		} "rule9";
		Organization.identifier as s1 where $this.system='https://ncez.mzcr.cz/fhir/sid/oddel' -> pracovisteType then {
			s1.value as x -> pracovisteType.oddel = x "rule10";
		} "rule11";
		Organization.identifier as s1 where $this.system='https://ncez.mzcr.cz/fhir/sid/pcz' -> pracovisteType then {
			s1.value as x -> pracovisteType.pcz = x "rule12";
		} "rule13";
		Organization -> pracovisteType.nazev as t1 then {
			Organization.name as x -> t1.txt = x "rule14";
		} "rule15";
}
group pracovnik(source Practitioner: Practitioner, target pracovnikType: pracovnikType){


		Practitioner.id as x -> pracovnikType.guid = x "rule1";

		Practitioner -> pracovnikType.titul_pred as t1 then {
			Practitioner.name as s1 -> t1 then {
				s1.prefix as x -> t1.txt = x "rule2";
			} "rule3";
		} "rule4";
		Practitioner -> pracovnikType.jmeno as t1 then {
			Practitioner.name as s1 -> t1 then {
				s1.given as x -> t1.txt = x "rule5";
			} "rule6";
		} "rule7";
		Practitioner -> pracovnikType.prijmeni as t1 then {
			Practitioner.name as s1 -> t1 then {
				s1.family as x -> t1.txt = x "rule8";
			} "rule9";
		} "rule10";
		Practitioner -> pracovnikType.titul_za as t1 then {
		  Practitioner.telecom as ContactPoint -> t1 then{
			Practitioner.name as s1 -> t1 then {
				s1.suffix as x -> t1.txt = x "rule11";
				s1.prefix as x1 -> t1 then{
				  s1.given as x2 -> t1 then{
				   s1.family as x3 -> t1 then{
				    s1.suffix as x4 -> append(x1, ' ', x2, ' ', x3, ' ', x4) as Name then {

						Practitioner.address as addr -> pracovnikType.a as y then adresa(ContactPoint,addr,Name,y) "rule13";
					}"";
				   }"";
				  }"";					
				}"";
			}"";
		  }"";
		}"";
			

}
group ku_z_lab(source bundle: Bundle, target ku_z_labType: ku_z_labType){


		bundle.entry as entry -> ku_z_labType   then {

			entry.resource as DiagnosticReport where $this.ofType(FHIR.DiagnosticReport) -> ku_z_labType then 
			       vrk(DiagnosticReport,bundle,ku_z_labType) "rule6";

			entry.resource as Observation where $this.ofType(FHIR.Observation) ->  ku_z_labType then 
			       vrb(bundle,Observation,ku_z_labType) "rule12";

			entry.resource as Observation where $this.ofType(FHIR.Observation) ->  ku_z_labType then 
			       vrs(bundle,Observation,ku_z_labType) "rule18";
				   
		    entry.resource as DiagnosticReport where $this.ofType(FHIR.DiagnosticReport) -> ku_z_labType then 
			       vrr(DiagnosticReport,bundle,ku_z_labType) "rule24";

			entry.resource as s1 where $this.ofType(FHIR.Observation) -> ku_z_labType then 
			      vrf(bundle,s1,ku_z_labType) "rule30";

			entry.resource as s1 where $this.ofType(FHIR.Observation) -> ku_z_labType then 
			    vrc(bundle,s1,ku_z_labType) "rule36";


			entry.resource as s1 where $this.ofType(FHIR.Observation) -> ku_z_labType then 
			    vrn(s1,bundle,ku_z_labType) "rule42";

			entry.resource as s1 where $this.ofType(FHIR.DiagnosticReport) -> ku_z_labType then 
			    vrz(bundle,s1,ku_z_labType) "rule48";

			entry.resource as s1 where $this.ofType(FHIR.Observation) ->  ku_z_labType then 
			    vrx(s1,bundle,ku_z_labType) "rule54";

			entry.resource as s1 where $this.ofType(FHIR.DiagnosticReport) ->  ku_z_labType then 
			    vro(bundle,s1,ku_z_labType) "rule60";
		}"";

}
group vrb(source entry: Bundle, source Observation: Observation, target ku_z_lab: ku_z_lab){

		Observation.code as s2 -> ku_z_lab then {
			s2.coding as s3 where 'https://dasta.mzcr.cz/cz-nclp-labpol-vs'=$this.system -> ku_z_lab then {
				s3.code as x -> ku_z_lab.klic_nclp = x "rule1";
			} "rule2";
		} "rule3";
		Observation.code as s2 -> ku_z_lab then {
			s2.coding as s3 where 'https://dasta.mzcr.cz/DSAKB.htm'=$this.system -> ku_z_lab then {
				s3.code as x -> ku_z_lab.syst_klic = x "rule4";
			} "rule5";
		} "rule6";
		Observation.code as s2 -> ku_z_lab then {
			s2.coding as s3 where 'https://dasta.mzcr.cz/DSAJQ.htm'=$this.system -> ku_z_lab then {
				s3.code as x -> ku_z_lab.komp_klic = x "rule7";


				entry -> ku_z_lab.typ_cispol = 'N' "rule8";
			} "rule9";
		} "rule10";
		Observation.code as s2 -> ku_z_lab then {
			s2.coding as s3 where 'https://dasta.mzcr.cz/DSAJN.htm'=$this.system -> ku_z_lab then {
				s3.code as x -> ku_z_lab.typpol_fh = x "rule11";
			} "rule12";
		} "rule13";
